def dedupe(rows):
    latest = {}
    first_seen = []

    for row in rows:
        order_id = row["order_id"]
        if order_id not in latest:
            first_seen.append(order_id)
            latest[order_id] = row
        elif row["updated_at"] >= latest[order_id]["updated_at"]:
            latest[order_id] = row

    return [latest[order_id] for order_id in first_seen]

